-- =====================================================================
-- posthog_events — PostHog posthog/models/event/event.py + ClickHouse events table materialized columns
-- 8000 rows of synthetic, type-correct data (real column
-- names/types, generated values). See ../00_schema_catalog.md for the
-- exact source file this schema was pulled from.
--
-- HOW TO USE:
--   Paste this whole file into the CockroachDB Cloud SQL Shell and run it.
--   No IMPORT INTO / external URL needed — plain batched INSERTs, so this
--   works on every CockroachDB Cloud tier with no fetch/network step.
-- =====================================================================

CREATE TABLE "posthog_events" (
    "id" INT8 NOT NULL,
    "created_at" TIMESTAMP NOT NULL,
    "team_id" INT8 NOT NULL,
    "event" STRING NOT NULL,
    "distinct_id" STRING NOT NULL,
    "properties" JSONB NOT NULL,
    "timestamp" TIMESTAMP NOT NULL,
    "elements_hash" STRING,
    "site_url" STRING NOT NULL,
    "elements" JSONB,
    "uuid" UUID NOT NULL,
    "person_id" UUID,
    "ip" INET NOT NULL,
    "current_url" STRING NOT NULL,
    "browser" STRING NOT NULL,
    "os" STRING NOT NULL,
    "device_type" STRING NOT NULL,
    "referrer" STRING,
    "session_id" UUID NOT NULL,
    "library" STRING NOT NULL,
    "library_version" STRING NOT NULL,
    PRIMARY KEY ("id")
);
















